def column_totals(rows):
    if not rows:
        return []
    result = []
    for i in range(len(rows[0])):
        total = 0
        has_numeric = False
        for r in rows:
            val = r[i]
            if isinstance(val, (int, float)):
                total += val
                has_numeric = True
        if has_numeric:
            result.append(total)
        else:
            result.append("")
    return result

def render_rows(rows, mark_last=False):
    rendered = []
    for idx, r in enumerate(rows):
        if mark_last and idx == len(rows) - 1:
            r = ["TOTAL"] + r
        rendered.append(",".join(str(v) for v in r))
    return rendered

from render import render_rows
from totals import column_totals


def export_csv(rows, totals=False):
    if totals:
        # Compute total row: ["TOTAL"] + column totals
        totals_row = ["TOTAL"] + column_totals(rows)
        rows = rows + [totals_row]
    return "\n".join(render_rows(rows))
